DROP TABLE IF EXISTS `modelos_mensagem`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `modelos_mensagem` (
  `id` char(36) NOT NULL DEFAULT (uuid()),
  `estabelecimento_id` char(36) NOT NULL,
  `nome` varchar(255) NOT NULL,
  `descricao` varchar(255) DEFAULT NULL,
  `categoria` varchar(60) DEFAULT NULL,
  `gatilho` text NOT NULL,
  `canal` enum('whatsapp','email','sms','app') NOT NULL DEFAULT 'whatsapp',
  `assunto` varchar(255) DEFAULT NULL,
  `texto` text NOT NULL,
  `status` enum('ativo','inativo') NOT NULL DEFAULT 'ativo',
  PRIMARY KEY (`id`),
  KEY `idx_modelos_estab` (`estabelecimento_id`),
  CONSTRAINT `modelos_mensagem_ibfk_1` FOREIGN KEY (`estabelecimento_id`) REFERENCES `estabelecimentos` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

