INSERT INTO `modelos_mensagem` VALUES ('md1','e1','Confirmação imediata','Confirmação automática ao criar o agendamento','Agendamento','Ao agendar','whatsapp',NULL,'Olá {cliente}! Seu horário na {estabelecimento} está confirmado para {data} às {hora} com {profissional}. Qualquer coisa, é só responder aqui. 💈','ativo'),('md2','e1','Lembrete véspera','Enviado 1 dia antes do atendimento','Agendamento','1 dia antes','whatsapp',NULL,'Oi {cliente}, passando pra lembrar do seu horário amanhã às {hora}. Confirma pra mim? Responda SIM ou NÃO.','ativo'),('md3','e1','Retorno (cliente sumido)','Para clientes sem visita há 60+ dias','Retenção','60 dias sem voltar','whatsapp',NULL,'E aí {cliente}, sentimos sua falta! Que tal dar um trato no visual? Tem horário essa semana. 😎','ativo'),('md4','e1','Aniversário','Parabéns com oferta especial no aniversário','Fidelidade','No aniversário','whatsapp',NULL,'Parabéns, {cliente}! 🎉 Pra comemorar, você tem 20% off no seu próximo corte esse mês. Vem!','ativo');
